  function expandCityStateAbbreviation(location2) {
    let parts = location2.split(",").map((part) => part.trim());
    if (parts.length < 2) return null;
    let stateKey = parts[1].replace(/\./g, "").toUpperCase();
    let mapped = STATE_MAP[stateKey];
    if (!mapped) return null;
    parts[1] = mapped;
    return parts.join(", ");
  }
  function formatAnswer49(answer) {
    if (answer.regular) {
      let nameLabels = ["First Name", "First name", "Last Name", "Last name"];
      for (let label of nameLabels) {
        if (answer.regular[label] && typeof answer.regular[label] === "string") {
          answer.regular[label] = toNameTitleCase(
            answer.regular[label]
          );
        }
      }
      answer.regular.Phone = resolvePhoneFieldValue(
        answer.regular.Phone?.replace(/[^\d+]/g, "") || "",
        resolvePhoneCountryCodeAnswer(answer)
      );
      let locationLabel = "Location (City)" in answer.regular ? "Location (City)" : "Location / City";
      let locationValue = answer.regular[locationLabel];
      if (locationValue != null) {
        let candidates = typeof locationValue === "string" ? [locationValue] : Array.isArray(locationValue) ? [...locationValue] : [];
        let expanded = [];
        for (let candidate of candidates) {
          if (typeof candidate !== "string") continue;
          candidate = candidate.replace(/,\s*(USA|United States?)$/i, "").trim();
          let withState = expandCityStateAbbreviation(candidate);
          if (withState && withState !== candidate) expanded.push(withState);
          expanded.push(candidate);
        }
        if (expanded.length > 0) {
          answer.regular[locationLabel] = expanded;
        }
      }
      let websiteKey = Object.keys(answer.regular).find(
        (key2) => key2.toLowerCase() === "website"
      );
      let hasLinkedIn = Object.keys(answer.regular).some(
        (key2) => /linkedin/i.test(key2)
      );
      if (websiteKey && hasLinkedIn) {
        let websiteValue = Array.isArray(answer.regular[websiteKey]) ? answer.regular[websiteKey][0] : answer.regular[websiteKey];
        if (typeof websiteValue === "string" && /linkedin\.com/i.test(websiteValue)) {
          delete answer.regular[websiteKey];
        }
      }
    }
    return answer;
  }

